local stats = {
    kills = 0, piles = 0, m1 = 0, casts = 0,
    castsTook = 0, castsMissed = 0, castsHit = 0,
    swaps = 0, flights = 0, hops = 0, pulledBack = 0, putBack = 0,
    escapes = 0, probes = 0, hakiPresses = 0, startedAt = 0,
}

local state          = "IDLE"
local statusLine     = "idle"
local stateEnteredAt = 0
local conns          = {}
local moveEnabled    = true
-- The invisible floor kept at the deep sea's surface (Submerged Island).
local waterFloor     = nil
local activeName     = nil     -- the species being fought right now
local countedDead    = {}
local circuitIdx     = 1

-- THE ABORT EPOCH. Every long operation captures this on entry and gives up
-- the moment it changes. Stop bumps it, so stop means stop.
local epoch = 0
local function stale(e) return e ~= epoch end

local function track(c) table.insert(conns, c) return c end
local function log(m) if CFG.Debug then print("[BFF] " .. tostring(m)) end end
local function say(s) statusLine = tostring(s) end

local function setState(s)
    if state ~= s then
        state = s
        stateEnteredAt = os.clock()
        log("state -> " .. s)
    end
end

-- =========================================================
-- CHARACTER
-- =========================================================
local function parts()
    local char = player.Character
    if not char then return nil end
    local root = char:FindFirstChild("HumanoidRootPart")
    local hum  = char:FindFirstChildOfClass("Humanoid")
    if not root or not hum or hum.Health <= 0 then return char, nil, nil end
    return char, root, hum
end

local function healthPct()
    local _, _, hum = parts()
    if not hum or hum.MaxHealth <= 0 then return 1 end
    return hum.Health / hum.MaxHealth
end

local function playerLevel()
    local ls = player:FindFirstChild("leaderstats")
    local lv = ls and ls:FindFirstChild("Level")
    if lv and tonumber(lv.Value) then return tonumber(lv.Value) end
    local d = player:FindFirstChild("Data")
    local l2 = d and d:FindFirstChild("Level")
    return l2 and tonumber(l2.Value) or nil
end

local function levelRow()
    local lv = playerLevel()
    if not lv then return nil end
    for _, row in ipairs(LEVELS) do
        if lv >= row[1] and lv <= row[2] then return row end
    end
    return LEVELS[#LEVELS]
end
P.levelRow = levelRow

local function heldTool()
    local char = player.Character
    return char and char:FindFirstChildOfClass("Tool")
end
P.heldTool = function()
    local t = heldTool()
    return t and t.Name or nil
end

-- A PHYSICAL FRUIT (one to eat or store, "Kitsune Fruit" with an EatRemote -
-- not your eaten fruit's power, "Kitsune-Kitsune") is never a weapon: it is
-- never listed, never equipped, and nothing is clicked while one is in your
-- hand. A click with it held EATS it and replaces your fruit (user, main
-- account, 2026-09-28). Roblox puts a tool you touch straight into your hand.
function P.isPhysicalFruit(t)
    if not (t and t:IsA("Tool")) then return false end
    if string.find(t.Name, " Fruit$") then return true end
    local ok, er = pcall(function() return t:FindFirstChild("EatRemote", true) end)
    return ok and er ~= nil
end

-- A FRUIT LYING IN THE WORLD (user, 2026-10-12: "the news never shows a
-- fruit the game spawned - only what players drop"). The probe of
-- 2026-09-28 (workspace/fruit_probe.txt) logged seven fruits, every one a
-- player's drop - a Tool "X Fruit" with OriginalName "X-X" - and both
-- finders asked for exactly that, so a spawn of any other shape was never
-- seen. Now the public hubs' rule (HOSTI, Kaitun, GGEZ, 2024-26): any child
-- of workspace, a Tool OR a Model, whose name has "Fruit" (or that carries
-- OriginalName), with a Handle - a Model's own, or its Tool's - and that is
-- not a player's character. Which fruit: OriginalName, else read from the
-- name ("Kitsune Fruit" -> "Kitsune-Kitsune", "Bird: Falcon Fruit" ->
-- "Bird-Bird: Falcon"); a name with no fruit in it ("Fruit ") = unknown.
-- -> { orig (nil = unknown), name, handle, tool } or nil.
function P.fruitOrig(name)
    local base = string.match(tostring(name), "^%s*(.-)%s+Fruit%s*$")
    if not base or base == "" then return nil end
    local a, b = string.match(base, "^([^:]+):%s*(.+)$")
    if a then return a .. "-" .. a .. ": " .. b end
    return base .. "-" .. base
end
-- WHICH FRUIT A SPAWN IS (user, 2026-10-24: "can it tell which fruit a
-- server spawn is, and its cost? I set 2.6 million and it still goes for
-- every fruit"). In game 2026-10-23 (bff_fruit_seen.txt) a spawn is a Model
-- "Fruit " with NO attributes - children Fruit (Model), FruitAnimator,
-- Handle - so it was always "unknown", and an unknown spawn was taken at
-- any price. What it looks like is the only name it has: the Fruit model's
-- meshes. Two readings, the first that answers:
--   1. a mesh named after its file, "Meshes/<fruit>_<n>" (the public
--      notifiers read it, 2023-25: "magu" = Magma, "smouke" = Smoke,
--      "quaketest" = Quake), matched against the game's price list
--   2. its LOOK, learned: every fruit whose name IS known - a player's drop
--      (OriginalName), one you picked up, one in your backpack - teaches its
--      MeshIds / TextureIDs -> that name (workspace/bff_fruit_looks.json).
--      A look two fruits share names neither.
local LOOKS_FILE = "bff_fruit_looks.json"
local MESH_ALIAS = { magu = "magma", smouke = "smoke", quaketest = "quake" }
-- Renamed fruits: the mesh file may keep the old name.
local RENAMED = { rumble = "lightning", lightning = "rumble", leopard = "tiger", tiger = "leopard",
    falcon = "eagle", eagle = "falcon" }
local NOT_A_FRUIT = { fruit = true, handle = true, stem = true, leaf = true, leaves = true, part = true, mesh = true }
local function norm(s) return string.lower((string.gsub(tostring(s), "[^%w]", ""))) end
-- "Kitsune-Kitsune" -> "Kitsune", "Bird-Bird: Falcon" -> "Falcon", "T-Rex-T-Rex" -> "T-Rex".
function P.fruitBase(orig)
    orig = tostring(orig)
    local sub = string.match(orig, ":%s*(.+)$")
    if sub then return sub end
    return string.match(orig, "^(.+)%-%1$") or orig
end
-- TRADE VALUE (user, 2026-10-25: "follow the trading market's value, not the
-- Beli the game asks"). A PHYSICAL fruit's value - never a permanent's or a
-- skin's. ONE SOURCE ONLY (user, 2026-11-15: "only Blox Fruits Values, the
-- other lists are outdated" - fruityblox had Venom at 10M while it trades at
-- 120M): bloxfruitsvalues.com/values, each fruit's regValue (records of
-- 2026-11-02 .. 11, read 2026-11-15). This is the MARKET scale: it decides
-- only "too good to lose" (CFG.FruitKeepValue) and the dearest-first order of
-- the news. Picking a fruit up is the GAME's Beli price (CFG.FruitMinPrice,
-- the dealer's GetFruits) - the two never mix.
-- Keyed by the fruit's own name ("Control" of "Control-Control"). Dragon is
-- one fruit in the game (West / East is picked once eaten): East's, the
-- lower, counts.
P.TRADE_VALUES = {
    Dragon = 2.31e9, Kitsune = 450e6, Magnet = 310e6, Venom = 120e6, Control = 90e6, Tiger = 80e6,
    Yeti = 70e6, Gas = 60e6, Dough = 30e6, Lightning = 20e6, ["T-Rex"] = 20e6,
    Pain = 10e6, Gravity = 10e6, Mammoth = 10e6, Spirit = 10e6, Portal = 10e6, Buddha = 10e6,
    Shadow = 6.5e6, Blizzard = 5e6, Phoenix = 2.75e6, Creation = 2.5e6, Sound = 2.5e6,
    Spider = 1.5e6, Love = 1.5e6, Magma = 1.15e6, Quake = 1e6, Diamond = 1e6, Light = 800e3,
    Ghost = 800e3, Eagle = 800e3, Rubber = 700e3, Ice = 550e3, Sand = 420e3, Dark = 400e3,
    Flame = 250e3, Spike = 180e3, Smoke = 100e3, Bomb = 80e3, Spring = 60e3, Blade = 50e3,
    Spin = 7.5e3, Rocket = 5e3,
}
-- "Buddha-Buddha" -> "Buddha": its name on this list and on your fruit menu;
-- nil = a fruit the list does not know (newer than it).
do
    local byNorm = {}
    for name in pairs(P.TRADE_VALUES) do byNorm[norm(name)] = name end
    function P.fruitKey(orig)
        if orig == nil then return nil end
        local want = norm(P.fruitBase(orig))
        if string.find(want, "dragon", 1, true) then return "Dragon" end
        return byNorm[want] or byNorm[RENAMED[want] or ""]
    end
end
-- -> its trade value; nil = a fruit the list does not know (newer than it).
function P.tradeValue(orig)
    local k = P.fruitKey(orig)
    return k and P.TRADE_VALUES[k] or nil
end
-- Your mark on the fruit menu: "take", "skip", or nil (the limit decides).
function P.fruitChoice(orig)
    local k = P.fruitKey(orig)
    return k and CFG.FruitMenu[k] or nil
end
-- Too good to lose (CFG.FruitKeepValue): worth at least `min` - a fruit the
-- list does not know counts too, a new one is dear until shown otherwise.
-- min 0 = nothing is.
function P.isKeeper(orig, min)
    min = tonumber(min) or 0
    if min <= 0 then return false end
    local v = P.tradeValue(orig)
    return v == nil or v >= min
end
-- 120000000 -> "120M", 2970000000 -> "2.97B", nil -> "?".
function P.valueWords(v)
    if type(v) ~= "number" then return "?" end
    if v >= 1e9 then return (string.gsub(string.format("%.2fB", v / 1e9), "%.?0+B$", "B")) end
    if v >= 1e6 then return (string.gsub(string.format("%.2fM", v / 1e6), "%.?0+M$", "M")) end
    if v >= 1e3 then return (string.gsub(string.format("%.1fK", v / 1e3), "%.?0+K$", "K")) end
    return tostring(v)
end

-- THE FRUIT HISTORY (user, 2026-10-25: "which fruits it gets, in which
-- server of the hops, how many of each, stored or not"). Every fruit picked
-- up, newest last, the last 300, in workspace/bff_fruit_log_<UserId>.json.
-- An entry: t (os.time), orig, value (trade), price (Beli), server (the
-- hunt's join count when it came), from ("spawn" / "drop"), isle, state.
-- The state changes as the fruit moves on: stored, backpack (kept for raid
-- chips), held (too good to lose, no free slot), notstored, slot (stored
-- once a slot was free), hopstored (stored right before a hop), gone (left
-- your backpack while held - traded, given, stored by you), lost (left
-- behind at a hop).
P.FRUIT_STATES = {
    stored = "stored", backpack = "in backpack, not stored", held = "HELD - no storage slot",
    notstored = "not stored - no slot", slot = "stored once a slot was free",
    hopstored = "stored before a hop", gone = "left the backpack - traded / stored by you",
    lost = "LOST - left behind at a hop",
    -- 2026-11-08 (a Tiger the history called stored was not in the user's
    -- storage): a store is only "stored" when the game's storage count went
    -- up. It left your hands, the count did not rise = VANISHED; the count
    -- not readable = not confirmed.
    unconfirmed = "NOT CONFIRMED - storage count not readable",
    vanished = "VANISHED - left your hands, never counted",
}
P.fruitLogFile = "bff_fruit_log_" .. tostring(player.UserId) .. ".json"
P.fruitLog = {}
pcall(function()
    local t = game:GetService("HttpService"):JSONDecode(readfile(P.fruitLogFile))
    if type(t) == "table" and type(t.log) == "table" then P.fruitLog = t.log end
end)
function P.fruitLogSave()
    if not writefile then return end
    pcall(function()
        writefile(P.fruitLogFile, game:GetService("HttpService"):JSONEncode({ v = 1, log = P.fruitLog }))
    end)
end
function P.fruitLogAdd(e)
    e.t = e.t or os.time()
    table.insert(P.fruitLog, e)
    while #P.fruitLog > 300 do table.remove(P.fruitLog, 1) end
    P.fruitLogSave()
    return e
end
-- The newest entry of `orig` whose state is one of `from` (a set) gets `state`.
-- -> the entry, or nil.
function P.fruitLogSet(orig, state, from)
    for i = #P.fruitLog, 1, -1 do
        local e = P.fruitLog[i]
        if e.orig == orig and (from == nil or from[e.state]) then
            e.state = state
            P.fruitLogSave()
            return e
        end
    end
    return nil
end
function P.fruitLogClear()
    table.clear(P.fruitLog)
    P.fruitLogSave()
end
-- Per fruit, dearest first: "Control   x2  ·  120M  ·  1 stored, 1 HELD...".
function P.fruitLogSummary()
    local by, order = {}, {}
    for _, e in ipairs(P.fruitLog) do
        local name = P.fruitBase(e.orig)
        local s = by[name]
        if not s then
            s = { name = name, n = 0, value = e.value, states = {} }
            by[name] = s
            table.insert(order, s)
        end
        s.n += 1
        s.states[e.state or "?"] = (s.states[e.state or "?"] or 0) + 1
    end
    table.sort(order, function(a, b)
        if (a.value or 0) ~= (b.value or 0) then return (a.value or 0) > (b.value or 0) end
        return a.name < b.name
    end)
    local lines = {}
    for _, s in ipairs(order) do
        local bits = {}
        for st, n in pairs(s.states) do
            table.insert(bits, string.format("%d %s", n, P.FRUIT_STATES[st] or st))
        end
        table.sort(bits)
        table.insert(lines, string.format("%-10s x%-3d %6s  ·  %s", s.name, s.n, P.valueWords(s.value),
            table.concat(bits, ", ")))
    end
    return lines
end
-- The newest `n` entries, newest first: "25 Oct 18:42  server #37  Dough  30M  HELD...".
function P.fruitLogLines(n)
    local lines = {}
    for i = #P.fruitLog, math.max(1, #P.fruitLog - (n or 40) + 1), -1 do
        local e = P.fruitLog[i]
        table.insert(lines, string.format("%s  server #%s  %-10s %6s  %s%s",
            os.date("%d %b %H:%M", e.t or 0), tostring(e.server or "?"), P.fruitBase(e.orig),
            P.valueWords(e.value), P.FRUIT_STATES[e.state] or tostring(e.state),
            e.from == "drop" and "  (a drop)" or ""))
    end
    return lines
end
-- "Meshes/magu_34" -> "magma"; nil = not a mesh named after a fruit.
function P.meshToken(name)
    local t = string.match(tostring(name), "^Meshes/([^_]+)")
    if not t then return nil end
    t = norm(string.gsub(t, "%d+", ""))
    if t == "" or NOT_A_FRUIT[t] then return nil end
    return MESH_ALIAS[t] or t
end
-- A token -> the game's name ("Magma-Magma") from the price list; no list
-- yet = the usual "X-X"; a list that has no such fruit = nil.
function P.fruitOfToken(tok, catalog)
    if not tok then return nil end
    local any = false
    for _, want in ipairs({ tok, RENAMED[tok] }) do
        for orig in pairs(catalog or {}) do
            any = true
            if norm(P.fruitBase(orig)) == want then return orig end
        end
    end
    if any then return nil end
    local cap = string.upper(string.sub(tok, 1, 1)) .. string.sub(tok, 2)
    return cap .. "-" .. cap
end
-- What a fruit looks like: its Fruit model's (else its own) meshes, as keys
-- "m<MeshId>" / "t<TextureID>", and the fruit a mesh's own name gives.
local function prop(d, k)
    local ok, v = pcall(function() return d[k] end)
    return ok and v or nil
end
function P.fruitLooks(c)
    local keys, seen, token = {}, {}, nil
    pcall(function()
        local root = c:FindFirstChild("Fruit") or c
        for _, d in ipairs(root:GetDescendants()) do
            if d:IsA("MeshPart") or d:IsA("SpecialMesh") or d:IsA("FileMesh") then
                local m = string.match(tostring(prop(d, "MeshId") or ""), "(%d+)%s*$")
                -- Fast Mode's thumbnail form ends in its size (...&id=123&w=150&h=150).
                local tx = tostring(prop(d, "TextureID") or prop(d, "TextureId") or "")
                local t = string.match(tx, "id=(%d+)") or string.match(tx, "(%d+)%s*$")
                for _, k in ipairs({ m and ("m" .. m), t and ("t" .. t) }) do
                    if not seen[k] then seen[k] = true table.insert(keys, k) end
                end
            end
            token = token or P.meshToken(d.Name)
        end
    end)
    table.sort(keys)
    return keys, token
end
-- Teach store: these keys look like `orig`. -> true if anything changed.
function P.looksLearn(store, keys, orig)
    if type(orig) ~= "string" or orig == "" then return false end
    local changed = false
    for _, k in ipairs(keys or {}) do
        local was = store[k]
        if was == nil then
            store[k], changed = orig, true
        elseif was ~= false and was ~= orig then
            store[k], changed = false, true          -- two fruits share it: names neither
        end
    end
    return changed
end
-- The fruit these keys name: every key that names a fruit names the same, and
-- they are at least 60% of the keys not shared. Every key had to be known once:
-- one mesh never read lost a fruit picked many times (user, 2026-11-07, "the
-- script will be locked about its information forever"). One shared glow on
-- a new fruit is still too few to take its name.
function P.looksName(store, keys)
    local name
    local known, unseen = 0, 0
    for _, k in ipairs(keys or {}) do
        local v = store[k]
        if v == nil then
            unseen += 1
        elseif type(v) == "string" then
            if name and name ~= v then return nil end
            name = v
            known += 1
        end
    end
    if known * 5 < (known + unseen) * 3 then return nil end
    return name
end
do
    local ok, t = pcall(function() return game:GetService("HttpService"):JSONDecode(readfile(LOOKS_FILE)) end)
    P.FRUIT_LOOKS = (ok and type(t) == "table") and t or {}
end
function P.looksSave()
    if not writefile then return end
    pcall(function() writefile(LOOKS_FILE, game:GetService("HttpService"):JSONEncode(P.FRUIT_LOOKS)) end)
end
-- A known fruit teaches its look (a drop's OriginalName, a pickup, the backpack).
function P.looksTeach(c, orig)
    local keys = P.fruitLooks(c)
    if P.looksLearn(P.FRUIT_LOOKS, keys, orig) then P.looksSave() end
end
P.fruitCatalog = P.fruitCatalog or {}         -- [orig] = price, the game's list (the fruit hunt reads it)
-- Fruits on the trade list with no look learned: a spawn of one has no name
-- until it is picked up once. Sorted: the panel's line holds still.
function P.looksMissing()
    local have, out = {}, {}
    for _, o in pairs(P.FRUIT_LOOKS) do
        local k = type(o) == "string" and P.fruitKey(o)
        if k then have[k] = true end
    end
    for n in pairs(P.TRADE_VALUES) do
        if not have[n] then table.insert(out, n) end
    end
    table.sort(out)
    return out
end
-- A fruit menu row's line: its Beli price, and what happens to it.
function P.menuWords(price, limit, choice)
    local what = (choice == "take" and "always taken") or (choice == "skip" and "never taken")
        or (not price and "no price yet")
        or ((price >= (limit or 0)) and "taken") or "under your limit"
    return price and ("$" .. P.valueWords(price) .. "  ·  " .. what) or what
end

-- THE FRUIT NEWS (user, 2026-11-08: "the important fruits I wanna know
-- before, and the unimportant fruits I don't even need to know" - 8 fruits
-- lying, Eagle, Flame, Rocket, Rubber... said first, a T-Rex server spawn
-- lost behind them). Of the fruits lying, ONLY the ones you care about:
-- Take on your fruit menu, a Mythical (the game's own price 2.5M Beli and
-- up - Gravity is the cheapest), or your limit and over (CFG.FruitMinPrice,
-- when above 0); Skip never. No price read yet: the market's list decides
-- (10M and up, or a fruit newer than the list). A server spawn not named
-- yet might be anything: said too.
--
-- ITS OWN RANGE (user, 2026-11-25: "for a new player maybe a rare fruit is
-- also good ... a range which fruit notification we will get, and other
-- fruits also, select specifically"). The news has its own limit and its own
-- marks, on the Breaking news page, like the fruit menu's:
--   1. your news mark: Show = always said, Hide = never;
--   2. your fruit menu: Take = said (what you take you hear of), Skip = not;
--   3. the news limit (CFG.NewsFruitMin, the game's Beli price): at least
--      it = said. 0 = every fruit. Its default, 2.5M, is the Mythical floor
--      the news had before, so nothing changes until you move it.
-- The fruit menu's own limit no longer decides the news.
P.MYTHICAL_PRICE = 2.5e6
function P.newsChoice(orig)
    local k = P.fruitKey(orig)
    return k and (CFG.NewsFruitMenu or {})[k] or nil
end
function P.fruitMatters(f, limit, choice, newsChoice)
    limit = tonumber(limit) or P.MYTHICAL_PRICE
    if f.orig == nil then return (not f.dropper) or limit <= 0 end
    local said = newsChoice and newsChoice(f.orig) or nil
    if said == "show" then return true end
    if said == "hide" then return false end
    local mark = choice and choice(f.orig) or nil
    if mark == "skip" then return false end
    if mark == "take" then return true end
    if limit <= 0 then return true end
    local p = tonumber(f.price)
    if not p then
        local v = P.tradeValue(f.orig)
        return v == nil or v >= 10e6
    end
    return p >= limit
end
-- A news row's line: its Beli price, and whether it is said.
function P.newsWords(price, limit, said, mark)
    limit = tonumber(limit) or P.MYTHICAL_PRICE
    local what = (said == "show" and "always told") or (said == "hide" and "never told")
        or (mark == "take" and "told - you take it") or (mark == "skip" and "not told - you skip it")
        or ((limit <= 0) and "told")
        or (not price and "no price yet")
        or ((price >= limit) and "told") or "under your news limit"
    return price and ("$" .. P.valueWords(price) .. "  ·  " .. what) or what
end
-- -> the ones you care about, DEAREST FIRST (the market's trade value; the
-- game's price for a fruit the list does not know; one not named yet
-- last), a server spawn before a player's drop of the same worth; and how
-- many others lie here, not said.
function P.fruitNews(list, limit, choice, newsChoice)
    local keep, hidden = {}, 0
    for _, f in ipairs(list) do
        if P.fruitMatters(f, limit, choice, newsChoice) then
            local v = f.orig and (P.tradeValue(f.orig) or tonumber(f.price) or 0) or -1
            table.insert(keep, { f = f, v = v })
        else
            hidden += 1
        end
    end
    table.sort(keep, function(a, b)
        if a.v ~= b.v then return a.v > b.v end
        local sa, sb = not a.f.dropper, not b.f.dropper
        if sa ~= sb then return sa end
        return tostring(a.f.name) < tostring(b.f.name)
    end)
    local out = {}
    for i, k in ipairs(keep) do out[i] = k.f end
    return out, hidden
end
-- "T-Rex 20M (server spawn, Hydra Island)", "Dough 30M (dropped, Mansion)".
function P.fruitNewsWords(f)
    local where = (f.dropper and "dropped" or "server spawn") .. (f.isle and (", " .. f.isle) or "")
    if not f.orig then return "a fruit not named yet (" .. where .. ")" end
    local v = P.tradeValue(f.orig)
    local worth = v and P.valueWords(v) or (f.price and ("$" .. P.valueWords(f.price))) or "?"
    return string.format("%s %s (%s)", P.fruitKey(f.orig) or P.fruitBase(f.orig), worth, where)
end
-- One fruit lying, the same one however often the game makes it again (it
-- streams out and back in as a new instance: the same Ice Fruit was news
-- every 15 s for 10 min, 2026-11-08 logs): its name and its 16-stud square.
function P.fruitSpot(f)
    local p = f.pos
    return tostring(f.orig or f.name) .. "@" .. (p and (math.floor(p.X / 16) .. "," .. math.floor(p.Z / 16)) or "?")
end

-- STILL ARRIVING (user, 2026-11-13: "it does not recognise the Shadow fruit
-- though I took it many times - some fruits it knows, some it does not").
-- The logs of that day: a spawn is first seen with the game's own attributes
-- ExpectedDescendants (= 123 for the Shadow) / ExpectedDescendantsNames -
-- its parts are still streaming in (the game's Util.WaitForExpectedDescendants
-- waits on exactly these and clears them when all are there). Read then, a
-- big fruit has no mesh yet: no name, and with "unknown spawn" on it was
-- gone for whatever it was - the small ones (Spin: 3 meshes) were complete
-- and named. true = not all there yet: nothing is decided on it.
function P.fruitLoading(c)
    local ok, exp = pcall(function() return c:GetAttribute("ExpectedDescendants") end)
    exp = ok and tonumber(exp) or nil
    if not exp then return false end
    local okN, n = pcall(function() return #c:GetDescendants() end)
    return not (okN and n >= exp)
end
-- The first of `list` (fruitsLying) not named because it is still arriving,
-- and waited for less than maxWait since first seen (seen: [tool] = when);
-- nil = nothing to wait for. -> the fruit, the seconds left.
function P.fruitHold(list, now, seen, maxWait)
    maxWait = tonumber(maxWait) or 8
    for _, f in ipairs(list) do
        if f.loading and f.orig == nil and f.tool ~= nil then
            seen[f.tool] = seen[f.tool] or now
            local left = maxWait - (now - seen[f.tool])
            if left > 0 then return f, left end
        end
    end
    return nil, 0
end
-- YOUR STORAGE IS FULL OF IT (user, 2026-11-13: "I can store 3 of the same
-- fruit - one I can store is stored at once; one I cannot, it should say").
-- cap = player.Data.FruitCap (how many of EACH fruit your storage holds),
-- else the number the game's own "storage full" answer gave. A fruit you
-- already hold that many of cannot be stored: it is left where it lies -
-- except one too good to lose (CFG.FruitKeepValue), which is still taken
-- and held safe. -> true + how many you have + the cap.
function P.fruitFull(orig, stock, cap, countFn)
    cap = tonumber(cap)
    if not (orig and type(stock) == "table" and cap and cap > 0 and countFn) then return false end
    local n = tonumber(countFn(stock, orig)) or 0
    return n >= cap, n, cap
end
-- The size, most sure first: the number the game itself gave with a "storage
-- full" (this server); else player.Data.FruitCap - never under what you
-- demonstrably hold of one fruit (stock), should that value mean something
-- else than read here. -> the cap, where it is from.
function P.fruitCapNow(stock)
    if P.fruitCapSeen then return P.fruitCapSeen, "the game's 'storage full' answer" end
    local ok, v = pcall(function() return player.Data.FruitCap.Value end)
    v = ok and tonumber(v) or nil
    if not (v and v > 0) then return nil, "not read" end
    local most = 0
    for _, c in pairs(type(stock) == "table" and stock or {}) do
        most = math.max(most, tonumber(c) or 0)
    end
    if most > v then return most, "what you hold of one fruit (FruitCap said less)" end
    return v, "the game's FruitCap"
end

function P.groundFruit(c)
    if not (c and (c:IsA("Tool") or c:IsA("Model"))) then return nil end
    local name = tostring(c.Name)
    local orig = c:GetAttribute("OriginalName")
    if type(orig) ~= "string" and not string.find(name, "Fruit", 1, true) then return nil end
    if Players:FindFirstChild(name) then return nil end        -- someone's character
    local h = c:FindFirstChild("Handle")
    if not (h and h:IsA("BasePart")) and c:IsA("Model") then
        local t = c:FindFirstChildWhichIsA("Tool")
        h = t and t:FindFirstChild("Handle")
    end
    if not (h and h:IsA("BasePart")) then return nil end
    local how, looks, loading = nil, nil, false
    if type(orig) == "string" then
        how = "tag"
        P.looksTeach(c, orig)                                  -- a known fruit teaches its look
    else
        loading = P.fruitLoading(c)
        orig = P.fruitOrig(name)
        if orig then
            how = "name"
        else
            local token
            looks, token = P.fruitLooks(c)
            orig = P.fruitOfToken(token, P.fruitCatalog)
            how = orig and "mesh name" or nil
            if not orig then
                orig = P.looksName(P.FRUIT_LOOKS, looks)
                how = orig and "look learned" or nil
            end
            -- Not one mesh to read yet: arriving, whatever its attributes say.
            if not orig and #looks == 0 then loading = true end
        end
    end
    -- A spawn read from its look shows its fruit's name, not "Fruit ".
    local label = (orig and not P.fruitOrig(name) and not c:GetAttribute("OriginalName"))
        and (P.fruitBase(orig) .. " Fruit") or name
    return { orig = orig, name = label, handle = h, tool = c, how = how, looks = looks, loading = loading and orig == nil }
end

-- WHERE (user, 2026-10-24: "which island is it on?"): the nearest of the
-- game's own place markers (workspace._WorldOrigin.Locations - the names it
-- shows when you arrive), flat distance; a raid's "Island N" is no place.
-- Farther than 1500 studs from every one = out at sea.
function P.isleOf(pos)
    local wo = pos and workspace:FindFirstChild("_WorldOrigin")
    local locs = wo and wo:FindFirstChild("Locations")
    if not locs then return nil end
    local best, bd
    for _, l in ipairs(locs:GetChildren()) do
        if not string.match(tostring(l.Name), "^Island %d") then
            local ok, p = pcall(function() return l:IsA("BasePart") and l.Position or l:GetPivot().Position end)
            if ok and p then
                local dx, dz = p.X - pos.X, p.Z - pos.Z
                local d = math.sqrt(dx * dx + dz * dz)
                if not bd or d < bd then best, bd = l.Name, d end
            end
        end
    end
    if not best then return nil end
    if bd > 1500 then return string.format("at sea, %.1fk from %s", bd / 1000, best) end
    return best
end
-- What a fruit in the world looks like, written ONCE per shape (its class,
-- whose, its attribute names, its children) to the console and
-- workspace/bff_fruit_seen.txt - the first game spawn tells us what the
-- game makes. `why`: why it was not taken, if it was not.
do
local fruitShapes, fruitLog = {}, {}
function P.fruitShape(c, why)
    pcall(function()
        local an, av, kids = {}, {}, {}
        for k, v in pairs(c:GetAttributes()) do
            table.insert(an, tostring(k))
            table.insert(av, tostring(k) .. "=" .. tostring(v))
        end
        for _, d in ipairs(c:GetChildren()) do table.insert(kids, d.Name .. ":" .. d.ClassName) end
        table.sort(an) table.sort(av) table.sort(kids)
        local whose = c:GetAttribute("DroppedBy") and "DROP" or "SPAWN"
        local key = c.ClassName .. "|" .. whose .. "|" .. table.concat(an, ",") .. "|" .. table.concat(kids, ",")
        if fruitShapes[key] then return end
        fruitShapes[key] = true
        -- Inside its Fruit model (2026-10-24): what a spawn's look is made
        -- of - the meshes' names and asset ids, the first 12.
        local inner = {}
        local fm = c:FindFirstChild("Fruit")
        if fm then
            pcall(function()
                for _, d in ipairs(fm:GetDescendants()) do
                    if #inner >= 12 then break end
                    local m = prop(d, "MeshId")
                    local t = prop(d, "TextureID") or prop(d, "TextureId")
                    table.insert(inner, d.Name .. ":" .. d.ClassName
                        .. ((m and m ~= "") and (" m=" .. tostring(m)) or "") .. ((t and t ~= "") and (" t=" .. tostring(t)) or ""))
                end
            end)
        end
        local line = string.format("[BFF] fruit seen (%s%s): Name=%q Class=%s  attributes: %s  children: %s%s",
            whose, why and (" - " .. why) or "", c.Name, c.ClassName,
            (#av > 0) and table.concat(av, ", ") or "(none)", (#kids > 0) and table.concat(kids, ", ") or "(none)",
            (#inner > 0) and ("  inside Fruit: " .. table.concat(inner, ", ")) or "")
        print(line)
        table.insert(fruitLog, os.date("%Y-%m-%d %H:%M  ") .. line)
        if writefile then pcall(writefile, "bff_fruit_seen.txt", table.concat(fruitLog, "\n")) end
    end)
end
end

local function findTool(name)
    local bp   = player:FindFirstChild("Backpack")
    local char = player.Character
    local t = (char and char:FindFirstChild(name)) or (bp and bp:FindFirstChild(name))
    if t and t:IsA("Tool") and not P.isPhysicalFruit(t) then return t end
    return nil
end

local function toolNames()
    local out, seen = {}, {}
    -- Not ipairs: it stops at the first nil (no Backpack for a moment).
    local srcs = { player:FindFirstChild("Backpack"), player.Character }
    for i = 1, 2 do
        local src = srcs[i]
        if src then
            for _, t in ipairs(src:GetChildren()) do
                if t:IsA("Tool") and not seen[t.Name] and not P.isPhysicalFruit(t) then
                    seen[t.Name] = true
                    table.insert(out, t)
                end
            end
        end
    end
    return out
end

-- "Blox Fruit", "Melee", "Sword", "Gun" -- the game's own label on the tool.
local function toolType(tool)
    if not tool then return "?" end
    local tip = tool.ToolTip
    if type(tip) == "string" and #tip > 0 then return tip end
    local wt = tool:GetAttribute("WeaponType")
    return wt and tostring(wt) or "?"
end
P.toolType = toolType

-- =========================================================
-- INPUT
-- =========================================================
local function pressKey(code)
    pcall(function()
        VIM:SendKeyEvent(true, code, false, game)
        task.wait(0.04)
        VIM:SendKeyEvent(false, code, false, game)
    end)
end

-- Some skills fire on release after a hold; the hold is yours, per key.
-- `before`, if given, runs right before each of the two key events (the
-- hidden aim puts the camera on the pile for exactly that instant).
local function holdKey(code, secs, before)
    if before then before() end
    pcall(function() VIM:SendKeyEvent(true, code, false, game) end)
    task.wait(math.max(secs or 0.05, 0.03))
    if before then before() end
    pcall(function() VIM:SendKeyEvent(false, code, false, game) end)
end

local function pressM1()
    -- A fruit in hand: the click would EAT it. Put it away instead.
    local held = heldTool()
    if held and P.isPhysicalFruit(held) then
        local _, _, h = parts()
        if h then pcall(function() h:UnequipTools() end) end
        return
    end
    local cam = workspace.CurrentCamera
    if not cam then return end
    local vs = cam.ViewportSize
    local x, y = vs.X * 0.5, vs.Y * 0.5
    pcall(function() VIM:SendMouseButtonEvent(x, y, 0, true, game, 0) end)
    task.wait(0.04)
    pcall(function() VIM:SendMouseButtonEvent(x, y, 0, false, game, 0) end)
    pcall(function()
        VirtualUser:CaptureController()
        VirtualUser:Button1Down(Vector2.new(x, y), cam.CFrame)
        VirtualUser:Button1Up(Vector2.new(x, y), cam.CFrame)
    end)
end

-- =========================================================
-- REMOTES
-- =========================================================
-- Looked up when first needed, never at load: a lookup made before the game
-- has finished building is nil for the whole session (farm_pro learned that
-- one the hard way with the spawn folders).
local function commF()
    local r = RS:FindFirstChild("Remotes")
    return r and r:FindFirstChild("CommF_")
end

-- ReplicatedStorage.Modules.Net holds the combat remotes as "RE/<name>" and
-- "RF/<name>". The public hubs also reach them through the Net module itself
-- (require(Net):RemoteEvent(name, true)), which creates one if it is missing.
-- Direct child first, the module second.
local netCache = {}
local function netRemote(kind, name)
    local key = kind .. "/" .. name
    local hit = netCache[key]
    if hit and hit.Parent then return hit end
    local mods = RS:FindFirstChild("Modules")
    local net  = mods and mods:FindFirstChild("Net")
    if not net then return nil end
    local r = net:FindFirstChild(key)
    if not r then
        local okM, mod = pcall(require, net)
        if okM and type(mod) == "table" then
            local fn = (kind == "RE") and mod.RemoteEvent or mod.RemoteFunction
            if type(fn) == "function" then
                local okR, rr = pcall(fn, mod, name, true)
                if okR and typeof(rr) == "Instance" then r = rr end
            end
        end
    end
    netCache[key] = r
    return r
end
P.netRemote = netRemote

-- =========================================================
-- BODY: NOCLIP AND THE LOCK
-- =========================================================
-- Two per-frame jobs while the farm runs, and they are what make everything
-- else possible:
--   before physics : every part of the character stops colliding
--   after physics  : the body is written to the lock and its velocity zeroed
-- The Humanoid puts collisions back on some of its own parts every step and
-- gravity pulls every frame, so a single write is always undone; these run
-- every frame. With collisions off and nothing holding it, a body falls
-- through the map -- so the body is ALWAYS held: at the lock, or, if there is
-- no lock yet, wherever it is.
local lockCF      = nil
local flying      = false
local lastWritten = nil      -- where this script last put the body
local savedCollide = {}
local bodyChar, bodyList, bodyListAt = nil, {}, 0

local SUB_Y = -1000          -- below this = Submerged Island (the deep sea)

-- WATER IS ROCK, EVERY MODE (user, 2026-10-11, the Legendary Sword hunt at
-- Kingdom of Rose: "water should be solid on every mode when the script is
-- on - I will glide on the water, not penetrate it"). Noclip turns the
-- character's collisions off every frame, so the raised sea slab (WALK ON
-- WATER) cannot hold the body: a flight's straight line to a point under the
-- water - or a lock on one - went through the island and into the sea under
-- it (water damage, death). Only a sea fight had a floor (P.floorY). Now the
-- line is in the writes themselves: the body is never put lower than the
-- sea's top + 4 (the root over the feet) - the lock, every frame, a flight,
-- an instant hop. Only over the sea slab's own footprint, and not down in
-- the deep sea (Submerged Island has its own floor).
do
    local slab, slabAt = nil, -1e9
    -- The lowest the ROOT may be written at pos, or nil. The top as walk on
    -- water raises it (Size.Y 112 = the surface), read as the middle + 56 so
    -- it holds before the raise too.
    function P.waterLine(pos)
        if pos.Y < SUB_Y then return nil end
        local now = os.clock()
        if now - slabAt > 2 or not (slab and slab.Parent) then
            slabAt = now
            local map = workspace:FindFirstChild("Map")
            local p = map and map:FindFirstChild("WaterBase-Plane")
            slab = (p and p:IsA("BasePart")) and p or nil
        end
        if not slab then return nil end
        local ok, top = pcall(function()
            local lp = slab.CFrame:PointToObjectSpace(pos)
            local sz = slab.Size
            if math.abs(lp.X) > sz.X / 2 or math.abs(lp.Z) > sz.Z / 2 then return nil end
            return slab.Position.Y + math.max(sz.Y / 2, 56)
        end)
        if not ok or not top then return nil end
        return top + 4
    end
    -- The floor at pos: the water line, or a sea fight's own if higher.
    function P.floorAt(pos)
        local fy, wl = P.floorY, P.waterLine(pos)
        if wl and (not fy or wl > fy) then fy = wl end
        return fy
    end
end

local function charParts(char)
    local out = {}
    for _, d in ipairs(char:GetDescendants()) do
        if d:IsA("BasePart") then table.insert(out, d) end
    end
    return out
end

local function bodyStepped()
    if not P.running or P.handsOff then return end
    local char = player.Character
    if not char then return end
    if char ~= bodyChar or os.clock() - bodyListAt > 0.5 then
        bodyChar, bodyList, bodyListAt = char, charParts(char), os.clock()
    end
    for _, p in ipairs(bodyList) do
        if p.Parent then
            if savedCollide[p] == nil then savedCollide[p] = p.CanCollide end
            p.CanCollide = false
        end
    end
end

local function bodyHeartbeat()
    if not P.running or P.handsOff then return end
    local _, r, h = parts()
    if not r or not h then return end
    h.AutoRotate = false
    if not flying then
        -- SOMETHING ELSE MOVED THE BODY. A respawn, the submarine, the game's
        -- own teleport: the body is far from where this script last put it.
        -- Stay where the game put us instead of dragging the body back.
        -- P.keepLock (SEA EVENTS): a move under 500 studs is a knockback or a
        -- pull (a Terrorshark's) - not adopted, the body goes back; a respawn
        -- or a teleport is still followed.
        local moved = lastWritten and (r.Position - lastWritten).Magnitude or 0
        if moved > 50 and not (P.keepLock and moved < 500) then
            local rot = lockCF and (lockCF - lockCF.Position) or (r.CFrame - r.CFrame.Position)
            lockCF = CFrame.new(r.Position) * rot
        end
        if not lockCF then lockCF = r.CFrame end
        local fy = P.floorAt(lockCF.Position)
        if fy and lockCF.Position.Y < fy then lockCF = lockCF + Vector3.new(0, fy - lockCF.Position.Y, 0) end
        r.CFrame = lockCF
        lastWritten = lockCF.Position
    end
    r.AssemblyLinearVelocity  = Vector3.zero
    r.AssemblyAngularVelocity = Vector3.zero
end

local function restoreBody()
    for part, was in pairs(savedCollide) do
        if part.Parent then pcall(function() part.CanCollide = was end) end
    end
    table.clear(savedCollide)
    local _, _, h = parts()
    if h then pcall(function() h.AutoRotate = true end) end
end

-- NO CHAIRS (user, 2026-11-07: "anything that is totally automated, it should
-- not be able to sit"). A cafe chair catches a body that passes through it -
-- noclip stops collisions, not Touched - and its SeatWeld then holds the body:
-- on your screen the lock has you at the NPC, the chair has you where it
-- stands. No route round the chairs: getting up is the whole fix, every mode
-- gets it at once, and the cafe stays usable. Every frame a mode runs (never
-- idle, never PvP: P.start and P.pvpSet exclude each other), seated anywhere
-- but the wheel a sea hunt is at = out, the same frame.
-- NOT Humanoid state Seated off: the weld forms anyway (DevForum), and the
-- boats need the state. NOT Seat.Disabled: disabling an occupied seat can stop
-- the character sitting anywhere afterwards - the wheel included.
do
    local off = {}                      -- [seat] = times it caught you this run
    local toldSeat, toldAt = nil, -1e9

    -- The one way out of a seat: Space, as a player gets up, then the two
    -- writes the wheel has always used.
    function P.leaveSeat(h)
        local seat = h.SeatPart
        if not seat then return end
        pcall(function() h.Jump = true end)
        pcall(function() h.Sit = false end)
        for _, w in ipairs(seat:GetChildren()) do
            if w.Name == "SeatWeld" then pcall(function() w:Destroy() end) end
        end
    end

    function P.seatGuard()
        if not P.running then return end
        local _, _, h = parts()
        local seat = h and h.SeatPart
        if not seat then return end
        local S = P.sea
        if S and ((S.driving and seat == S.seat) or seat == S.boarding) then return end
        P.leaveSeat(h)
        -- The chair off on your client, so one you hover over cannot catch you
        -- every few seconds. Unproven alone: "caught 2" in the log = it does
        -- not stop the touch, and only the getting up above is doing the work.
        off[seat] = (off[seat] or 0) + 1
        pcall(function() seat.CanTouch = false end)
        local now = os.clock()
        if seat ~= toldSeat or now - toldAt > 5 then
            toldSeat, toldAt = seat, now
            local ok, where = pcall(function() return seat:GetFullName() end)
            print(string.format("[BFF] seat: got up from %s (caught %d)",
                ok and tostring(where) or tostring(seat.Name), off[seat]))
        end
    end

    -- One seat back, before the script itself sits in it (a boat's wheel).
    function P.seatOn(seat)
        if off[seat] then
            off[seat] = nil
            pcall(function() seat.CanTouch = true end)
        end
    end

    -- Stop: every chair works again - idle and PvP are yours.
    function P.seatsBack()
        for seat in pairs(off) do
            pcall(function() seat.CanTouch = true end)
        end
        table.clear(off)
    end
end

-- Hold at pos, turned (yaw only) to face lookAt if given.
local function lockAt(pos, lookAt)
    -- THE WATER AS ROCK (a sea fight 2026-10-09, every mode 2026-10-11).
    local fy = P.floorAt(pos)
    if fy and pos.Y < fy then pos = Vector3.new(pos.X, fy, pos.Z) end
    if lookAt then
        local flat = Vector3.new(lookAt.X, pos.Y, lookAt.Z)
        if (flat - pos).Magnitude > 0.5 then
            lockCF = CFrame.lookAt(pos, flat)
            return
        end
    end
    local rot = lockCF and (lockCF - lockCF.Position) or CFrame.identity
    lockCF = CFrame.new(pos) * rot
end

-- =========================================================
-- THE CAMERA, BORROWED FOR A CAST AND GIVEN BACK
-- =========================================================
local aimPixel = nil         -- a synthetic click's own point; nil = where the mouse is
local aimUntil = 0           -- the hidden aim is put in every frame until this time
local releaseCamera, aimCamera, aimSwapIn, hiddenAim
do
    local InputService = game:GetService("UserInputService")
    local camHeld  = false
    local camBack  = nil         -- which side of the pile the camera stands, fixed while borrowed
    function releaseCamera()
        camBack = nil
        if not camHeld then return end
        camHeld = false
        local cam = workspace.CurrentCamera
        if not cam then return end
        pcall(function()
            local _, _, hum = parts()
            if hum then cam.CameraSubject = hum end
            cam.CameraType = Enum.CameraType.Custom
        end)
    end
    P.releaseCamera = releaseCamera

    -- A skill fires down the line from the camera through the cursor. Instead of
    -- moving the cursor, the camera is turned so that line goes through the pile:
    -- the cursor can be anywhere, the pile is under it. Yaw and pitch only (no
    -- roll), solved exactly:
    --   d = the cursor's direction in the camera's own frame (it depends only on
    --       the cursor's pixel and the field of view, not on where the camera is)
    --   t = the direction from the camera to the pile
    --   find pitch th, yaw psi with  Ry(psi) * Rx(th) * d = t
    --   height first (yaw leaves it alone): d.Y cos th - d.Z sin th = t.Y
    --   then yaw turns the flat part of Rx(th)*d onto the flat part of t.
    local function rayAim(at, target, dl)
        local t = target - at
        if t.Magnitude < 0.01 or dl.Magnitude < 0.01 then return CFrame.new(at) end
        t, dl = t.Unit, dl.Unit
        local amp = math.sqrt(dl.Y * dl.Y + dl.Z * dl.Z)
        if amp < 1e-4 then return CFrame.lookAt(at, target) end
        local phi = math.atan2(dl.Z, dl.Y)
        local ac = math.acos(math.clamp(t.Y / amp, -1, 1))
        local function wrap(x) return (x + math.pi) % (2 * math.pi) - math.pi end
        local th1, th2 = wrap(ac - phi), wrap(-ac - phi)
        local th = (math.abs(th1) <= math.abs(th2)) and th1 or th2
        local z1 = dl.Y * math.sin(th) + dl.Z * math.cos(th)
        local psi = math.atan2(t.X, t.Z) - math.atan2(dl.X, z1)
        return CFrame.new(at) * CFrame.Angles(0, psi, 0) * CFrame.Angles(th, 0, 0)
    end

    -- Where the camera stands. Looking down at an angle e, the pile can only
    -- be put under the cursor without rolling the view if
    --   sin(e) <= sqrt(d.Y^2 + d.Z^2)
    -- -- a cursor near a side edge cannot be pointed steeply down. So the
    -- camera stands CamDistance from the pile, on `away`'s side, as high as
    -- CamPitch, and lower when the cursor is near a side edge: the solve is
    -- then always exact, wherever the cursor is.
    local function aimFrame(target, away, dl)
        local d = dl.Unit
        local amp = math.sqrt(d.Y * d.Y + d.Z * d.Z)
        local e = math.min(math.rad(CFG.CamPitch or 55), math.asin(math.min(amp, 1)) * 0.95)
        -- P.camDistance: a fight's own (SEA EVENTS: a beast is bigger than 30
        -- studs - a camera inside it casts its ray from inside, and misses it).
        local at = target + (away * math.cos(e) + Vector3.new(0, math.sin(e), 0)) * (P.camDistance or CFG.CamDistance or 30)
        return rayAim(at, target, d)
    end

    -- Turn the camera so the line through the cursor (or through aimPixel, for
    -- a synthetic click) lands on targetPos. Called every frame while the pile
    -- is being hit, and right before each cast. centre = the pile's middle.
    function aimCamera(targetPos, centre)
        local cam = workspace.CurrentCamera
        local _, r = parts()
        if not cam or not r then return end
        -- The camera stands on your side of the pile's MIDDLE (not of the body
        -- aimed at: that one sits on the ring, and when it dies the next one
        -- is on another side -- the view would jump). Straight above the
        -- middle: on the side it stood when it was borrowed -- never worked
        -- out from its CURRENT facing, which this turns every frame.
        local c = centre or targetPos
        local away = Vector3.new(r.Position.X - c.X, 0, r.Position.Z - c.Z)
        if away.Magnitude < 1 then
            if not camBack then
                local lv = cam.CFrame.LookVector
                local f = Vector3.new(-lv.X, 0, -lv.Z)
                camBack = (f.Magnitude > 0.1) and f.Unit or Vector3.new(0, 0, 1)
            end
            away = camBack
        end
        pcall(function()
            local px = aimPixel or InputService:GetMouseLocation()
            local ray = cam:ViewportPointToRay(px.X, px.Y)
            local dl = cam.CFrame:VectorToObjectSpace(ray.Direction)
            cam.CameraType = Enum.CameraType.Scriptable
            camHeld = true
            cam.CFrame = aimFrame(targetPos, away.Unit, dl)
        end)
    end

    -- THE HIDDEN AIM: your camera stays yours. One frame goes
    --   input (keys are read) -> camera update (render step "Camera") ->
    --   drawn -> physics -> Heartbeat -> the next frame's input
    -- Whatever the camera is between Heartbeat and the next camera update is
    -- never drawn -- yet a key sent then is read inside that window. So: just
    -- after the camera updates, your view is saved; at Heartbeat the aim goes
    -- in; just before the next camera update your view goes back. The camera
    -- script and your screen only ever see your own view; the key sees the aim.
    local savedCF, swapped = nil, false
    function aimSwapIn(targetPos, centre)
        local cam = workspace.CurrentCamera
        if not cam or not savedCF then return end
        local c = centre or targetPos
        local away = Vector3.new(savedCF.Position.X - c.X, 0, savedCF.Position.Z - c.Z)
        if away.Magnitude < 1 then away = Vector3.new(0, 0, 1) end
        pcall(function()
            local px = aimPixel or InputService:GetMouseLocation()
            local ray = cam:ViewportPointToRay(px.X, px.Y)
            local dl = cam.CFrame:VectorToObjectSpace(ray.Direction)
            cam.CFrame = aimFrame(targetPos, away.Unit, dl)
            swapped = true
        end)
    end

    -- Bound while the farm runs (on) and removed at stop (off).
    function hiddenAim(on)
        pcall(function() RunService:UnbindFromRenderStep("BFFAimOut") end)
        pcall(function() RunService:UnbindFromRenderStep("BFFAimSave") end)
        local cam = workspace.CurrentCamera
        if swapped and cam and savedCF then pcall(function() cam.CFrame = savedCF end) end
        swapped, savedCF = false, nil
        if not on then return end
        pcall(function()
            RunService:BindToRenderStep("BFFAimOut", Enum.RenderPriority.Camera.Value - 1, function()
                if not swapped then return end
                swapped = false
                local c = workspace.CurrentCamera
                if c and savedCF then c.CFrame = savedCF end
            end)
            RunService:BindToRenderStep("BFFAimSave", Enum.RenderPriority.Camera.Value + 1, function()
                local c = workspace.CurrentCamera
                if c and not swapped then savedCF = c.CFrame end
            end)
        end)
    end
end

-- =========================================================
-- TRAVEL
-- =========================================================
-- Short: one write. Long: a straight line at TravelSpeed, written every
-- frame, collisions off, so there is nothing in the way to go round. "Pulled
-- back" counts frames where the body was not where it was written -- that is
-- the server correcting you, and the sign the speed is too high.
local TIKI_SUB = Vector3.new(-16269, 23, 1371)        -- the Submarine Worker (SUB_Y: BODY)
P.lastFlight = "none yet"

local function flatFace(pos, dir)
    local flat = Vector3.new(dir.X, 0, dir.Z)
    if flat.Magnitude < 0.1 then
        local rot = lockCF and (lockCF - lockCF.Position) or CFrame.identity
        return CFrame.new(pos) * rot
    end
    return CFrame.lookAt(pos, pos + flat)
end

