        P.kit.pageTop(v, "owner")
        readout(v, function()
            local log = P.fruitLog or {}
            local lines = { string.format("picked    %d fruits%s", #log,
                (#log > 0) and (" · since " .. os.date("%d %b %H:%M", log[1].t or 0)) or "") }
            local held = P.elite and P.elite.keepHeld
            if held and next(held) then table.insert(lines, "now       " .. tostring(P.elite.fruitNote)) end
            table.insert(lines, "server #  the hunt's join count when it came (Servers & team)")
            return table.concat(lines, "\n")
        end)
        P.kit.sectionRight(v, "each fruit - dearest first")
        readout(v, function()
            local s = P.fruitLogSummary()
            return (#s > 0) and table.concat(s, "\n") or "none yet"
        end)
        P.kit.sectionRight(v, "newest first")
        readout(v, function()
            local s = P.fruitLogLines(40)
            return (#s > 0) and table.concat(s, "\n") or "none yet"
        end)
        fold(v, "Clear it", function(v)
            caption(v, "Empties the history for good - the file too "
                .. "(workspace/bff_fruit_log_<your id>.json).")
            actionRow(v, "Clear the fruit history", nil, function() P.fruitLogClear() end)
        end)
    end

    -- =====================================================
    -- TRADES (P.trades): how many are left, when they come back
    -- =====================================================
    do
        local v = makeView("trades")
        gap(v, 6)
        P.kit.pageTop(v, "owner")
        readout(v, function() return P.trades.report() end)
        P.kit.sectionRight(v, "the rule")
        readout(v, function() return P.trades.rules() end)
        P.kit.sectionRight(v, "newest first")
        readout(v, function()
            local s = P.trades.lines(30)
            return (#s > 0) and table.concat(s, "\n") or "none yet"
        end)
        fold(v, "Clear it", function(v)
            caption(v, "Forgets every trade seen on this account - the file too "
                .. "(workspace/bff_trades_<your id>.json).")
            actionRow(v, "Forget the trades", nil, function() P.trades.clear() end)
        end)
        fold(v, "How it works", function(v)
            caption(v, "After every trade that goes through, the game says \"Trade completed (2/5)\". "
                .. "That count is the game's own: the script reads it (and the trade itself) and "
                .. "never sends anything.")
            caption(v, "When they come back is a rule. The wiki's \"5 a day, new day 11:59 PM UTC+8\" "
                .. "is wrong: jodl_37's own trades disprove it. Four rules fit all of them; the first "
                .. "one still standing is shown, and each count the game says rules out any rule "
                .. "that counted more than the game did.")
            caption(v, "Trades made while the script was not loaded are counted from the game's next "
                .. "count; until then a time reads \"by\": the latest it can be.")
        end)
        fold(v, "Details", function(v)
            caption(v, "Everything the game said about trades, newest first.")
            readout(v, function()
                local s = P.trades.noteLines()
                return (#s > 0) and table.concat(s, "\n") or "nothing about trades yet"
            end)
        end)
    end

    -- =====================================================
    -- HAKI BERRIES
    -- =====================================================
    do
        local v = makeView("berry")
        gap(v, 6)
        P.kit.pageTop(v, "owner")
        P.kit.modeStrip(v, "berry")
        readout(v, function()
            local el = P.elite
            local lines = { "last      " .. tostring(el.berryNote),
                string.format("picked    %d", el.tally.berries or 0) }
            if el.have.read then
                local bits = {}
                for _, n in ipairs(P.BERRIES) do
                    table.insert(bits, string.format("%s %d", (string.gsub(n, " Berry$", "")), el.have[n] or 0))
                end
                table.insert(lines, "you have  " .. table.concat(bits, " · "))
            end
            local _, r = parts()
            local ok, list = pcall(P.berriesLying)
            if ok and type(list) == "table" and #list > 0 then
                for _, b in ipairs(list) do
                    table.insert(lines, string.format("   %s   %s", table.concat(b.names, " + "),
                        r and string.format("%.0f studs", (b.pos - r.Position).Magnitude) or ""))
                end
            else
                table.insert(lines, "on the bushes here: none")
            end
            return table.concat(lines, "\n")
        end)
        P.kit.sectionRight(v, "which berries")
        -- What each one makes at the Barista (recipes from the Barista Cousin).
        local BERRY_USE = {
            ["Pink Pig Berry"]     = "Winter Sky: 15  (Legendary)",
            ["White Cloud Berry"]  = "Snow White: 10  (Legendary)",
            ["Red Cherry Berry"]   = "Pure Red: 15  (Legendary)",
            ["Blue Icicle Berry"]  = "Absolute Zero 5, Blue Jeans 3",
            ["Green Toad Berry"]   = "Slimy Green 1, Green Lizard 1",
            ["Orange Berry"]       = "Orange Soda 1, Heat Wave 2",
            ["Purple Jelly Berry"] = "Plump Purple 3",
            ["Yellow Star Berry"]  = "Bright Yellow 1, Yellow Sunshine 1",
        }
        -- Next to each berry its first color (the whole list is in How it
        -- works): "Winter Sky: 15", not a cut-off "Winter Sky: 15  (Le...".
        local items, uses = {}, {}
        for _, n in ipairs(P.BERRIES) do
            local use = BERRY_USE[n] or ""
            table.insert(uses, n .. " - " .. use)
            table.insert(items, { n, string.match((string.gsub(use, "%s*%b()", "")), "^[^,]*"),
                function() return CFG.BerryWant[n] == true end,
                function(x) CFG.BerryWant[n] = x and true or false end })
        end
        ticks(v, items)
        link(v, "Servers & team", function() return CFG.HuntHop and "hop on" or "no hop" end, "servers")
        fold(v, "How it works", function(v)
            caption(v, "Haki colors - Legendary Aura berries. What each makes at the Barista: "
                .. table.concat(uses, ";  ") .. ".")
            caption(v, "At most 4 in a server, a new one every 15 min, gone after an "
                .. "hour - anyone can take one. The Barista makes the colors "
                .. "(+ 7,500 fragments for a Legendary).")
        end)
    end

    -- =====================================================
    -- AURA RECIPE
    -- =====================================================
    do
        local v = makeView("recipe")
        gap(v, 6)
        P.kit.pageTop(v, "owner")
        P.kit.modeStrip(v, "recipe")
        readout(v, function()
            local el = P.elite
            return table.concat({
                "here      " .. tostring(el.offer or "not asked yet"),
                "last      " .. tostring(el.recipeNote),
                string.format("learned   %d", el.tally.recipes or 0),
            }, "\n")
        end)
        P.kit.sectionRight(v, "which recipes")
        local items = {}
        for i, n in ipairs(P.RECIPES) do
            table.insert(items, { n, (i <= 3) and "Legendary" or "Rare",
                function() return CFG.RecipeWant[n] == true end,
                function(x) CFG.RecipeWant[n] = x and true or false end })
        end
        ticks(v, items)
        link(v, "Servers & team", function() return CFG.HuntHop and "hop on" or "no hop" end, "servers")
        fold(v, "How it works", function(v)
            caption(v, "Barista Cousin - the recipe you pick, else the next server. The three Legendary: rip_indra's buttons need all three.")
            caption(v, "He teaches ONE recipe per server, asked from anywhere - no "
                .. "flight to find out. He comes 20 min after a server starts, "
                .. "stays 20, is gone 2. Switch off the ones you already have. A "
                .. "recipe learned goes off by itself; not learned (fragments, Aura "
                .. "stage 5) stops the hunt and says why.")
